    @SerialName("contact_name") val contactName: String? = null,
    val owner: String? = null,
    @SerialName("stage_id") val stageId: String,
    val status: String,
    @SerialName("lost_reason") val lostReason: String,
    @SerialName("expected_close") val expectedClose: ULong? = null,
    val source: String,
    /** Win probability: the stage's while open, 100 when won, 0 when lost. */
    val probability: UInt,
    @SerialName("stage_entered_at") val stageEnteredAt: ULong,
    @SerialName("closed_at") val closedAt: ULong? = null,
    @SerialName("next_activity") val nextActivity: NextActivity? = null,
    @SerialName("open_activities") val openActivities: UInt,
    /** The most recent completed activity or note, if any. */
    @SerialName("last_touch_at") val lastTouchAt: ULong? = null,
    @SerialName("created_by") val createdBy: String,
    @SerialName("created_at") val createdAt: ULong,
)

@Serializable
data class Event_ActivityChanged(
    val id: String,
)

@Serializable
data class Event_AutomationFired(
    @SerialName("automation_id") val automationId: String,
    @SerialName("deal_id") val dealId: String,
)

@Serializable
data class Event_ContactChanged(
    val id: String,
)

@Serializable
data class Event_DealCreated(
    val id: String,
    @SerialName("stage_id") val stageId: String,
)

@Serializable
data class Event_DealDeleted(
    val id: String,
)

@Serializable
data class Event_DealMoved(
    val id: String,
    @SerialName("stage_id") val stageId: String,
)

@Serializable
data class Event_DealStatusChanged(
    val id: String,
    val status: String,
)

@Serializable
data class Event_DealUpdated(
    val id: String,
)

@Serializable
data class Event_NoteChanged(
    val id: String,
    @SerialName("deal_id") val dealId: String,
)

/** The earliest open activity on a deal — the "next step" the board shows. */
@Serializable
data class NextActivity(
    val id: String,
    val kind: String,
    val subject: String,
    @SerialName("due_at") val dueAt: ULong,
)

/**
 * A note on a deal. Immutable once written; only its author may delete it —
 * the author being the entry's owner stamp, not a field.
 */
@Serializable
data class Note(
    val id: String,
    @SerialName("deal_id") val dealId: String,
    val body: String,
    @SerialName("created_at") val createdAt: ULong,
)

@Serializable
data class NoteView(
    val id: String,
    @SerialName("deal_id") val dealId: String,
    val author: String,
    val body: String,
    @SerialName("created_at") val createdAt: ULong,
)

@Serializable
data class Settings(
    val currency: String,
    @SerialName("rotting_days") val rottingDays: UInt,
)

/** A column of the pipeline. */
@Serializable
data class Stage(
    val id: String,
    val name: String,
    /** Win probability in percent, 0..=100. Drives the weighted forecast. */
    val probability: UInt,
    /** Sort key. Reordering rewrites every stage's position in one call. */
    val position: UInt,
    @SerialName("created_at") val createdAt: ULong,
)

@Serializable
data class StageView(
    val id: String,
    val name: String,
    val probability: UInt,
    val position: UInt,
)
